  "agent_name": "attraction",
  "summary": "为期3天（2026-08-07开始），3人北京游，目标在城市内、总预算上限7000元（仅目的地花费、不含出发地交通）。基于离线POI数据，选择了故宫博物院、天坛公园、颐和园、中国国家博物馆、南锣鼓巷、什刹海、八达岭长城、798艺术区和中国科学技术馆等景点作为备选与日程排序。已考虑各景点的门票已知性、室内/室外比例与推荐参观时长，按每人门票与中等餐饮/交通/住宿估算的可行性给出风险提示和预算建议。",
  "decisions": {
    "selected_poi_ids": [
      "bj001",
      "bj002",
      "bj003",
      "bj004",
      "bj005",
      "bj006",
      "bj007",
      "bj010",
      "bj011"
    ],
    "rejected_poi_ids": [],
    "selection_reasoning": {
      "bj001": "故宫：经典必去，门票已知（60元/人），室内混合，适合文化游。",
      "bj002": "天坛：世界遗产、开放式公园，适合早晨或半天游览，门票信息缺失但通常价格较低。",
      "bj003": "颐和园：皇家园林、推荐时长长，户外为主，适合半天到全天行程。",
      "bj004": "中国国家博物馆：室内为主且对雨天友好，适合调整到不良天气日。",
      "bj005": "南锣鼓巷：胡同与小吃街，适合体验北京生活与用餐。",
      "bj006": "什刹海：夜游或轻松散步安排，强度低，适合作为放松项。",
      "bj007": "八达岭长城：经典户外景点，推荐半天到全天，需安排交通与较高体力投入。",
      "bj010": "798艺术区：艺术与拍照，室内/室外混合，强度低，适合下午放松。",
      "bj011": "中国科学技术馆：室内、适合在雨天或计划中的博物馆日安排，推荐时长较长。"
    }
  },
  "risks": {
    "weather": {
      "risk_days": [
        {
          "date": "2026-08-07",
          "risk_level": "unknown",
          "notes": "离线数据无实时天气。所选多为户外/混合景点（颐和园、天坛、八达岭、南锣鼓巷、什刹海、奥林匹克公园等），若遇雨或极端高温可能影响体验与路线，应按需将室内博物馆（中国国家博物馆、中国科学技术馆）作为备选。"
        },
        {
          "date": "2026-08-08",
          "risk_level": "unknown",
          "notes": "同上。"
        },
        {
          "date": "2026-08-09",
          "risk_level": "unknown",
          "notes": "同上。"
        }
      ],
      "adjustment_required": true,
      "adjustment_notes": "建议在出发前查看实时天气并把室内景点（bj004、bj011）安排到有降雨或高温的日子；若天气良好优先安排颐和园与八达岭等户外重游。"
    },
    "other": [
      {
        "type": "ticket_price_uncertainty",
        "pois_affected": [
          "bj002",
          "bj003",
          "bj005",
          "bj006",
          "bj007",
          "bj008",
